void bubble_sort(vector<int>& a) {
    int n = a.size();
    for (int i = 0; i < n; i++) {
        for (int j = 0; j + 1 < n; j++) {
            if (a[j] > a[j + 1]) swap(a[j], a[j + 1]);
        }
    }
}

void merge_sort(vector<int>& a, vector<int>& tmp, int l, int r) {
    if (l >= r) return;
    int mid = l + (r - l) / 2;
    merge_sort(a, tmp, l, mid);
    merge_sort(a, tmp, mid + 1, r);

int i = l, j = mid + 1, k = l;
while (i <= mid && j <= r) {
    if (a[i] <= a[j]) tmp[k++] = a[i++];
    else tmp[k++] = a[j++];
}

    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r) tmp[k++] = a[j++];
    for (int pos = l; pos <= r; pos++) a[pos] = tmp[pos];
}

void count_sort(vector<int>& a, int c) {
    vector<int> cnt(c + 1);
    for (int x : a) cnt[x]++;
    int pos = 0;
    for (int x = 0; x <= c; x++) {
        for (int k = 0; k < cnt[x]; k++) a[pos++] = x;
    }
}

